       CAST(NULL AS STRING),
       CAST(0.0 AS DOUBLE),
       'P2_alert',
       'Customer',
       'dq-stewards-customer',
       'L2',
       'shadow',
       current_timestamp(),
       current_user(),
       current_timestamp(),
       CAST(NULL AS STRING),
       CAST(NULL AS TIMESTAMP),
       'Extracted 2026-10-05 from the workspace query \'Phone\' (known placeholder or prohibited, all-zeros pattern). The query\'s two versions carried different lists (42 and 14 numbers); this is their union, held once in dq.fn.is_phone_placeholder_v1 since v2. Adding a number is a _v2 of the helper and a new version of both rules.'
WHERE  NOT EXISTS (SELECT 1 FROM workspace.dq_triage.dq_config_rule_registry WHERE rule_id = 'CTCT_MOBL_PLACEHOLDER');

