-- =====================================================================
-- Part 3 — verification, read-only
-- =====================================================================

-- 3a — EXPECTED: one row, shadow 34.
SELECT status, COUNT(*) AS rules
FROM   workspace.dq_triage.dq_config_v_rule_registry_current
WHERE  rule_id IN ('CTCT_FRST_NM_NOT_NULL', 'CTCT_FRST_NM_PLACEHOLDER', 'CTCT_FRST_NM_FORMATTING', 'CTCT_FRST_NM_CONTAMINATED', 'CTCT_FRST_NM_LENGTH', 'CTCT_FRST_NM_STRUCTURE', 'CTCT_LAST_NM_NOT_NULL', 'CTCT_LAST_NM_PLACEHOLDER', 'CTCT_LAST_NM_FORMATTING', 'CTCT_LAST_NM_CONTAMINATED', 'CTCT_LAST_NM_LENGTH', 'CTCT_LAST_NM_STRUCTURE', 'CTCT_MID_NM_PLACEHOLDER', 'CTCT_MID_NM_FORMATTING', 'CTCT_MID_NM_CONTAMINATED', 'CTCT_MID_NM_LENGTH', 'CTCT_MID_NM_STRUCTURE', 'CTCT_PHN_AU_FMT', 'CTCT_PHN_WASHABLE', 'CTCT_PHN_PLACEHOLDER', 'CTCT_MOBL_AU_FMT', 'CTCT_MOBL_WASHABLE', 'CTCT_MOBL_PLACEHOLDER', 'CTCT_MOBL_SHARED', 'CTCT_BRTH_NOT_NULL', 'CTCT_BRTH_FUTURE', 'CTCT_BRTH_UNDER_14', 'CTCT_BRTH_MINOR_REVIEW', 'CTCT_BRTH_OVER_110', 'CTCT_BRTH_PLACEHOLDER', 'CTCT_ID_NOT_NULL', 'CTCT_ID_NUMERIC', 'CTCT_ID_FORMATTING', 'CTCT_ID_UNIQUE')
GROUP  BY status;

-- 3b — EXPECTED: zero rows. Every new rule names an element that binds its column.
SELECT r.rule_id, r.cde_id, r.target_column
FROM   workspace.dq_triage.dq_config_v_rule_registry_current r
LEFT JOIN (SELECT c.cde_id, b.target_table, b.target_column
           FROM workspace.dq_triage.dq_config_v_cde_registry_current c LATERAL VIEW explode(c.bindings) x AS b
           WHERE c.status = 'registered' AND b.binding_status = 'bound') e
  ON  e.cde_id = r.cde_id AND e.target_table = r.target_table
  AND e.target_column = r.target_column
WHERE r.rule_id IN ('CTCT_FRST_NM_NOT_NULL', 'CTCT_FRST_NM_PLACEHOLDER', 'CTCT_FRST_NM_FORMATTING', 'CTCT_FRST_NM_CONTAMINATED', 'CTCT_FRST_NM_LENGTH', 'CTCT_FRST_NM_STRUCTURE', 'CTCT_LAST_NM_NOT_NULL', 'CTCT_LAST_NM_PLACEHOLDER', 'CTCT_LAST_NM_FORMATTING', 'CTCT_LAST_NM_CONTAMINATED', 'CTCT_LAST_NM_LENGTH', 'CTCT_LAST_NM_STRUCTURE', 'CTCT_MID_NM_PLACEHOLDER', 'CTCT_MID_NM_FORMATTING', 'CTCT_MID_NM_CONTAMINATED', 'CTCT_MID_NM_LENGTH', 'CTCT_MID_NM_STRUCTURE', 'CTCT_PHN_AU_FMT', 'CTCT_PHN_WASHABLE', 'CTCT_PHN_PLACEHOLDER', 'CTCT_MOBL_AU_FMT', 'CTCT_MOBL_WASHABLE', 'CTCT_MOBL_PLACEHOLDER', 'CTCT_MOBL_SHARED', 'CTCT_BRTH_NOT_NULL', 'CTCT_BRTH_FUTURE', 'CTCT_BRTH_UNDER_14', 'CTCT_BRTH_MINOR_REVIEW', 'CTCT_BRTH_OVER_110', 'CTCT_BRTH_PLACEHOLDER', 'CTCT_ID_NOT_NULL', 'CTCT_ID_NUMERIC', 'CTCT_ID_FORMATTING', 'CTCT_ID_UNIQUE') AND e.cde_id IS NULL;

-- 3c — EXPECTED: zero rows. Nothing left pointing at a canonical name.
SELECT rule_id FROM workspace.dq_triage.dq_config_v_rule_registry_current
WHERE  rule_id IN ('CTCT_FRST_NM_NOT_NULL', 'CTCT_FRST_NM_PLACEHOLDER', 'CTCT_FRST_NM_FORMATTING', 'CTCT_FRST_NM_CONTAMINATED', 'CTCT_FRST_NM_LENGTH', 'CTCT_FRST_NM_STRUCTURE', 'CTCT_LAST_NM_NOT_NULL', 'CTCT_LAST_NM_PLACEHOLDER', 'CTCT_LAST_NM_FORMATTING', 'CTCT_LAST_NM_CONTAMINATED', 'CTCT_LAST_NM_LENGTH', 'CTCT_LAST_NM_STRUCTURE', 'CTCT_MID_NM_PLACEHOLDER', 'CTCT_MID_NM_FORMATTING', 'CTCT_MID_NM_CONTAMINATED', 'CTCT_MID_NM_LENGTH', 'CTCT_MID_NM_STRUCTURE', 'CTCT_PHN_AU_FMT', 'CTCT_PHN_WASHABLE', 'CTCT_PHN_PLACEHOLDER', 'CTCT_MOBL_AU_FMT', 'CTCT_MOBL_WASHABLE', 'CTCT_MOBL_PLACEHOLDER', 'CTCT_MOBL_SHARED', 'CTCT_BRTH_NOT_NULL', 'CTCT_BRTH_FUTURE', 'CTCT_BRTH_UNDER_14', 'CTCT_BRTH_MINOR_REVIEW', 'CTCT_BRTH_OVER_110', 'CTCT_BRTH_PLACEHOLDER', 'CTCT_ID_NOT_NULL', 'CTCT_ID_NUMERIC', 'CTCT_ID_FORMATTING', 'CTCT_ID_UNIQUE') AND (rule_expr LIKE '%dq.fn.%' OR scope_filter LIKE '%dq.fn.%'
       OR target_table LIKE 'prod.%');

-- 3d — coverage after. Shadow rules do not count, so only the two new bindings
-- move it: CTCT_ID by the orphan check tagged on its element, MID_NM by name
-- agreement. Compare with the run before.
SELECT coverage_gap, COUNT(*) AS bindings FROM workspace.dq_triage.dq_results_v_cde_coverage GROUP BY coverage_gap ORDER BY 1;
